.merkez {
    display: flex;
    justify-content: center; /* Yatay */
    align-items: center;     /* Dikey */
    height: 100vh;
}

.nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 2rem;
}

.nav-linkler {
    display: flex;
    gap: 1.5rem;
    list-style: none;
}

.kart-izgara {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
}

.kart {
    flex: 1 1 300px; /* büyü | küçül | temel genişlik */
}
